mapper.select:
SELECT id, display_name, status, version, created_at, updated_at
FROM guest_account
WHERE id = #{id}

SELECT account_id, subject, secret_hash
FROM guest_credential
WHERE provider = 'USERNAME' AND subject = #{subject}

SELECT account_id
FROM guest_credential
WHERE provider = #{provider} AND subject = #{subject}

mapper.update:
UPDATE guest_credential
SET verified_at = #{at}
WHERE account_id = #{accountId}
  AND provider = #{provider}
  AND subject = #{subject}
  AND verified_at IS NULL

mapper.select:
SELECT account_id, id_number_mask, real_name_mask, status, submitted_at, verified_at
FROM guest_id_verification
WHERE account_id = #{accountId}

SELECT account_id
FROM guest_id_verification
WHERE id_number_hmac = #{idNumberHmac}

mapper.update:
UPDATE guest_session
SET revoked_at = #{at}, revoke_reason = #{reason}, version = version + 1
WHERE account_id = #{accountId}
  AND revoked_at IS NULL
  AND expires_at > #{at}

UPDATE guest_id_verification
SET status      = #{decision},
    verified_at = #{verifiedAt},
    updated_at  = #{at}
WHERE account_id = #{accountId}
  AND status = 'PENDING'

mapper.select:
SELECT id, account_id, provider, subject, code_hash, expires_at, attempts, consumed_at
FROM guest_ownership_challenge
WHERE id = #{id}

mapper.update:
UPDATE guest_ownership_challenge
SET consumed_at = #{at}
WHERE id = #{id}
  AND consumed_at IS NULL
  AND attempts < #{maxAttempts}
  AND expires_at > #{at}

mapper.select:
SELECT id, account_id, provider, subject, code_hash, expires_at, attempts, consumed_at
FROM guest_login_challenge
WHERE id = #{id}

mapper.update:
UPDATE guest_credential
SET secret_hash = #{secretHash}
WHERE account_id = #{accountId}
  AND provider = 'USERNAME'

UPDATE guest_session
SET revoked_at = #{at}, revoke_reason = #{reason}, version = version + 1
WHERE account_id = #{accountId}
  AND id != #{exceptSessionId}
  AND revoked_at IS NULL
  AND expires_at > #{at}

mapper.select:
SELECT id, account_id, provider, subject, code_hash, expires_at, attempts, consumed_at
FROM guest_password_reset_challenge
WHERE id = #{id}
